begin;

insert into shop_ingredient_prices (
  ingredient_key,
  cost_coins,
  label_i18n,
  icon_path
)
values (
  'pork-filling',
  7,
  '{"en":"Fresh ground pork","zh":"新鲜猪肉馅"}'::jsonb,
