  special_ingredient_slots_i18n = '{"en":[{"ingredientKey":"pork-filling","name":"Fresh ground pork","quantity":1}],"zh":[{"ingredientKey":"pork-filling","name":"新鲜猪肉馅","quantity":1}]}'::jsonb,
